import { randomUUID } from "node:crypto";
import { getDb, getPool } from "@/db";
import { storageCleanupJobs } from "@/db/schema";
import { activeStorageProvider, deleteObject, deletePrefix, type StorageProvider } from "@/lib/storage";
import { normalizeStorageKey, normalizeStoragePrefix } from "@/lib/storage-policy";
import { abortMultipartUpload } from "@/lib/railway-direct-upload";

type Transaction = Parameters<Parameters<ReturnType<typeof getDb>["transaction"]>[0]>[0];
export type CleanupTarget = { key: string; source: string; provider?: StorageProvider; recursive?: boolean; uploadId?: string };
export type QueuedCleanup = CleanupTarget & { id: string; provider: StorageProvider; kind: "object" | "prefix" | "multipart" };
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function cleanupTarget(target: CleanupTarget): Omit<QueuedCleanup, "id"> {
  const provider = target.provider ?? activeStorageProvider();
  if (provider !== "local" && provider !== "s3") throw new Error("Invalid cleanup provider");
  if (!/^[a-z0-9_-]{1,80}$/i.test(target.source)) throw new Error("Invalid cleanup source");
  const key = target.recursive ? normalizeStoragePrefix(target.key) : normalizeStorageKey(target.key);
  if (target.recursive) {
    const parts = key.split("/");
    if (parts.length !== 4 || parts[0] !== "private" || parts[1] !== "video-derived"
        || !/^[1-9]\d*$/.test(parts[2]) || !UUID.test(parts[3])) throw new Error("Broad cleanup prefix rejected");
  }
  if (target.uploadId !== undefined && (target.recursive || provider !== "s3" || !key.startsWith("private/video-source/")
      || !target.uploadId || target.uploadId.length > 2048 || /[\u0000-\u0020\u007f]/.test(target.uploadId))) throw new Error("Invalid multipart cleanup context");
  return { ...target, key, provider, kind: target.uploadId !== undefined ? "multipart" : target.recursive ? "prefix" : "object" };
}

/** Legacy single-PUT URLs remain reusable until expiry if the object is removed.
 * Keep the tombstoned private object until the maximum 15-minute signature plus
 * clock margin expires. Multipart receipts retire the upload ID instead. */
export function cleanupInitialDelayMs(target: Omit<QueuedCleanup, "id">) {
  return target.provider === "s3" && target.kind === "object" && target.key.startsWith("private/video-source/")
    && !/^mp-[0-9a-f-]{36}\.[a-z0-9]+$/i.test(target.key.split("/").at(-1) || "") ? 16 * 60_000 : 0;
}

/** Must be called inside the same transaction that removes the owning records. */
export async function enqueueStorageCleanupTx(tx: Transaction, targets: CleanupTarget[]): Promise<QueuedCleanup[]> {
  const unique = new Map<string, Omit<QueuedCleanup, "id">>();
  for (const target of targets) {
    const normalized = cleanupTarget(target);
    unique.set(JSON.stringify([normalized.provider, normalized.kind, normalized.key, normalized.uploadId]), normalized);
  }
  const jobs = [...unique.values()].map(target => ({ ...target, id: randomUUID() }));
  for (let offset = 0; offset < jobs.length; offset += 200) {
    await tx.insert(storageCleanupJobs).values(jobs.slice(offset, offset + 200).map(job => ({
      id: job.id, kind: job.kind, provider: job.provider, objectKey: job.key,
      uploadId: job.uploadId ?? null, source: job.source, availableAt: new Date(Date.now() + cleanupInitialDelayMs(job)),
    })));
  }
  return jobs;
}

export function cleanupRetrySeconds(attempts: number) {
  if (!Number.isSafeInteger(attempts) || attempts < 1) throw new Error("Invalid cleanup attempt");
  return Math.min(21_600, 5 * 2 ** Math.min(attempts - 1, 13));
}
type Claimed = { id: string; kind: "object" | "prefix" | "multipart"; provider: StorageProvider; object_key: string; upload_id: string | null; source: string; attempts: number; lease_token: string };

/** At-least-once, idempotent cleanup. A crashed worker's lease is reclaimed; stale acknowledgements cannot win. */
export async function runStorageCleanupBatch(options: { limit?: number; ids?: string[]; signal?: AbortSignal } = {}) {
  const limit = options.limit ?? 10;
  if (!Number.isSafeInteger(limit) || limit < 1 || limit > 10 || options.ids?.some(id => !UUID.test(id))) throw new Error("Invalid cleanup batch");
  if (options.ids?.length === 0) return { processed: 0, failed: 0, failures: [] as string[] };
  options.signal?.throwIfAborted();
  const pool = getPool(), token = randomUUID();
  const claimed = await pool.query<Claimed>(`
    WITH due AS (
      SELECT id FROM storage_cleanup_jobs
      WHERE (status = 'pending' AND available_at <= CURRENT_TIMESTAMP
        OR status = 'running' AND lease_until <= CURRENT_TIMESTAMP)
        AND ($2::text[] IS NULL OR id = ANY($2::text[]))
      ORDER BY available_at, id FOR UPDATE SKIP LOCKED LIMIT $1
    )
    UPDATE storage_cleanup_jobs j SET status='running', attempts=j.attempts+1,
      lease_until=CURRENT_TIMESTAMP + interval '150 seconds', lease_token=$3
    FROM due WHERE j.id=due.id RETURNING j.*`, [limit, options.ids ?? null, token]);
  let processed = 0, failed = 0;
  const failures: string[] = [];
  await Promise.all(claimed.rows.map(async job => {
    const deadline = AbortSignal.timeout(120_000);
    const signal = options.signal ? AbortSignal.any([options.signal, deadline]) : deadline;
    try {
      // Revalidate persistent payloads too; corrupted queue rows must never widen deletion.
      const target = cleanupTarget({ key: job.object_key, source: job.source, provider: job.provider,
        recursive: job.kind === "prefix", ...(job.kind === "multipart" ? { uploadId: job.upload_id ?? "" } : {}) });
      signal.throwIfAborted();
      if (target.kind === "multipart") {
        await abortMultipartUpload(target.key, target.uploadId!, signal);
        await deleteObject(target.key, target.provider, signal);
      }
      else if (target.kind === "prefix") await deletePrefix(target.key, target.provider, signal);
      else await deleteObject(target.key, target.provider, signal);
      const result = await pool.query("UPDATE storage_cleanup_jobs SET status='completed', completed_at=CURRENT_TIMESTAMP, lease_until=NULL, lease_token=NULL, last_error=NULL WHERE id=$1 AND lease_token=$2 AND status='running'", [job.id, job.lease_token]);
      processed += result.rowCount ?? 0;
    } catch {
      // Keep the job forever until success; no raw endpoint errors, credentials or signed URLs are persisted.
      await pool.query("UPDATE storage_cleanup_jobs SET status='pending', available_at=CURRENT_TIMESTAMP + $3 * interval '1 second', lease_until=NULL, lease_token=NULL, last_error='storage_cleanup_failed' WHERE id=$1 AND lease_token=$2 AND status='running'", [job.id, job.lease_token, cleanupRetrySeconds(job.attempts)]);
      failed++; failures.push(`${job.source}:${job.object_key}`);
    }
  }));
  return { processed, failed, failures };
}

export async function storageCleanupSummary() {
  const { rows } = await getPool().query(`SELECT
    count(*) FILTER (WHERE status <> 'completed')::integer AS pending,
    count(*) FILTER (WHERE status <> 'completed' AND attempts >= 5)::integer AS retrying,
    count(*) FILTER (WHERE status = 'running' AND lease_until <= CURRENT_TIMESTAMP)::integer AS expired_leases
    FROM storage_cleanup_jobs`);
  return rows[0] as { pending: number; retrying: number; expired_leases: number };
}

import { normalizeStorageKey, normalizeStoragePrefix } from "@/lib/storage-policy";
import type { CleanupTarget } from "@/lib/storage-cleanup";
export type VideoCleanupAsset = { id: number; objectKey: string; storageProvider: string; derivativesPrefix: string | null; hlsMasterObjectKey: string | null; thumbnailObjectKey: string | null };
export function videoCleanupTargets(asset: VideoCleanupAsset): CleanupTarget[] {
  const cleanup: CleanupTarget[] = [];
  // A row's provider is immutable cleanup context; a new default must not move
  // deletion to a different bucket or to a same-named local file.
  if (asset.storageProvider !== "local" && asset.storageProvider !== "s3") {
    throw new Error("مزود تخزين الفيديو غير معروف؛ راجع السجل قبل الحذف.");
  }
  const provider = asset.storageProvider;
  try {
    const source = normalizeStorageKey(asset.objectKey);
    const ownedPath = (value: string, prefix: boolean) => {
      const key = prefix ? normalizeStoragePrefix(value) : normalizeStorageKey(value);
      const parts = key.split("/");
      // Only one worker attempt belonging to this exact asset may be removed
      // recursively. A course-wide, asset-wide, foreign or malformed prefix
      // is never an acceptable substitute for missing derivative metadata.
      if (parts[0] !== "private" || parts[1] !== "video-derived" || parts[2] !== String(asset.id)
          || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(parts[3] || "")
          || (prefix ? parts.length !== 4 : parts.length < 5)) throw new Error("Unowned derivative path");
      return key;
    };
    const prefix = asset.derivativesPrefix ? ownedPath(asset.derivativesPrefix, true) : null;
    const exactKeys = [asset.hlsMasterObjectKey, asset.thumbnailObjectKey]
      .filter((key): key is string => Boolean(key)).map(key => ownedPath(key, false));
    cleanup.push({ key: source, source: "video", provider });
    if (prefix) cleanup.push({ key: prefix, source: "video-derived", provider, recursive: true });
    for (const key of exactKeys) {
      if (!prefix || !key.startsWith(prefix + "/")) cleanup.push({ key, source: "video-derived", provider });
    }
  } catch {
    throw new Error("مسار ملفات الفيديو غير آمن أو لا يتبع هذا الفيديو؛ راجع بيانات التخزين قبل الحذف.");
  }
  return cleanup;
}

;
}

